const fs = require('fs');
const path = require('path');
const { withAppBuildGradle, withDangerousMod, withGradleProperties } = require('@expo/config-plugins');

// Keeps release APKs small enough for IzzyOnDroid (about 30 MB per APK).
// v1.0.0 was 43 MB: 14 MB of unshrunk dex plus ~11 MB of native libraries
// per ABI. android/ is regenerated by `expo prebuild --clean`, so all of this
// is injected here.
//
// 1. R8 minify + resource shrinking for every release build (APK and AAB).
// 2. ABI splits: assembleRelease writes one APK per ABI plus a universal one.
//    The ABI list is the reactNativeArchitectures property (the one the React
//    Native Gradle plugin builds native code for), so the split APKs match it.
// 3. Keep rules for modules that reach Java through reflection or JNI and
//    ship no consumer ProGuard rules. Without them R8 strips classes that only
//    native code or RxAndroidBle reference, which fails at runtime, not at
//    build time. Any new native dependency without consumer rules needs a
//    check on a phone with a minified build.

const KEEP_RULES = `
# --- with-release-size: modules without consumer rules ---
# react-native-ble-plx and its RxAndroidBle / RxJava stack
-keep class com.bleplx.** { *; }
-keep class com.polidea.rxandroidble2.** { *; }
-dontwarn com.polidea.rxandroidble2.**
-keep class io.reactivex.** { *; }
-dontwarn io.reactivex.**
# Skia: Java classes called from C++ through JNI
-keep class com.shopify.reactnative.skia.** { *; }
# expo-sqlite: JNI bridge to the bundled SQLite
-keep class expo.modules.sqlite.** { *; }
# gesture-handler and screens: JNI entry points
-keep class com.swmansion.gesturehandler.** { *; }
-keep class com.swmansion.rnscreens.** { *; }
`;

const SPLITS = `
    splits {
        abi {
            enable true
            reset()
            include(*(findProperty('reactNativeArchitectures') ?: 'armeabi-v7a,arm64-v8a,x86,x86_64').split(',').collect { it.trim() })
            universalApk true
        }
    }
    // With splits on, the React Native plugin no longer sets ndk.abiFilters
    // (AGP rejects both together), so prebuilt AARs would add x86/x86_64
    // libraries to the universal APK: 12 MB of partial, unusable code.
    packagingOptions {
        jniLibs {
            def kodoAbis = (findProperty('reactNativeArchitectures') ?: 'armeabi-v7a,arm64-v8a,x86,x86_64').split(',').collect { it.trim() }
            ['armeabi-v7a', 'arm64-v8a', 'x86', 'x86_64'].findAll { !kodoAbis.contains(it) }.each { excludes += "lib/\${it}/**" }
        }
    }`;

// Per-ABI versionCodes: app.json versionCode × 10 + ABI digit, universal 0.
// F-Droid-format repos (IzzyOnDroid) identify an APK by versionCode, so APKs
// of one release must not share it; the universal APK gets the lowest code so
// a client prefers the ABI-specific build. The ×10 keeps codes rising across
// releases (v1.0.1 = 20/21/22; 2 before). Applies to debug builds too.
const ABI_VERSION_CODES = `

// with-release-size: per-ABI versionCodes (versionCode * 10 + ABI digit)
def kodoAbiCodes = ['armeabi-v7a': 1, 'arm64-v8a': 2, 'x86': 3, 'x86_64': 4]
androidComponents {
    onVariants(selector().all()) { variant ->
        // The React Native plugin adds pickFirsts like **/libreactnative.so,
        // which win over the x86 excludes above and kept 8 MB of x86
        // libraries in the universal APK. Narrow them to the built ABIs.
        def builtAbis = (findProperty('reactNativeArchitectures') ?: 'armeabi-v7a,arm64-v8a,x86,x86_64').split(',').collect { it.trim() }
        def picks = variant.packaging.jniLibs.pickFirsts.get()
        variant.packaging.jniLibs.pickFirsts.set(picks.collectMany { p ->
            p.startsWith('**/') ? builtAbis.collect { "**/\${it}/\${p.substring(3)}".toString() } : [p]
        })
        variant.outputs.each { output ->
            def abi = output.filters.find { it.filterType.name() == 'ABI' }?.identifier
            output.versionCode.set(android.defaultConfig.versionCode * 10 + (abi ? kodoAbiCodes[abi] : 0))
        }
    }
}
`;

module.exports = function withReleaseSize(config) {
  config = withGradleProperties(config, (config) => {
    const set = (key, value) => {
      const props = config.modResults;
      const entry = props.find((p) => p.type === 'property' && p.key === key);
      if (entry) entry.value = value;
      else props.push({ type: 'property', key, value });
    };
    set('android.enableMinifyInReleaseBuilds', 'true');
    set('android.enableShrinkResourcesInReleaseBuilds', 'true');
    return config;
  });

  config = withAppBuildGradle(config, (config) => {
    let gradle = config.modResults.contents;
    if (gradle.includes('universalApk')) return config;
    const androidBlock = /^android \{/m;
    if (!androidBlock.test(gradle)) {
      throw new Error('with-release-size: app/build.gradle layout changed; update the plugin.');
    }
    config.modResults.contents = gradle.replace(androidBlock, `android {${SPLITS}`) + ABI_VERSION_CODES;
    return config;
  });

  return withDangerousMod(config, [
    'android',
    (config) => {
      const file = path.join(config.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro');
      const rules = fs.readFileSync(file, 'utf8');
      if (!rules.includes('with-release-size')) fs.writeFileSync(file, rules + KEEP_RULES);
      return config;
    },
  ]);
};
